// Markup is generated by the compiler; native details also work without JS.
export function prepareFootnotes(root) {
  root.classList.add('footnotes-interactive');
  let active;
  const refs = note => root.querySelectorAll(`a[data-note="${note.id}"]`);
  const sync = note => refs(note).forEach(ref => ref.setAttribute('aria-expanded', String(note.open)));
  const open = note => {
    if (active && active !== note && !active.contains(note) && !note.contains(active)) {
      for (let note = active; note; note = note.parentElement) {
        if (note.matches?.('details.inline-footnote')) {
          note.open = false;
          sync(note);
        }
      }
    }
    if (!active || !note.contains(active)) active = note;
  };
  root.addEventListener('click', event => {
    const ref = event.target.closest('a[data-note]');
    if (!ref || !root.contains(ref)) return;
    const note = root.ownerDocument.getElementById(ref.dataset.note);
    if (!note?.matches('details.inline-footnote')) return;
    event.preventDefault();
    if (note.open) note.open = false;
    else {
      open(note);
      for (let parent = note; parent; parent = parent.parentElement) {
        if (parent.tagName === 'DETAILS') {
          parent.open = true;
          if (parent.matches('details.inline-footnote')) sync(parent);
        }
      }
    }
    sync(note);
  });
  root.addEventListener('toggle', event => {
    const note = event.target;
    if (!note.matches('details.inline-footnote')) return;
    if (note.open) open(note);
    sync(note);
  }, true);
}
